CREATE OR REPLACE FUNCTION public.get_credit_wallet() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth AS $$ DECLARE v_user_id uuid := auth.uid(); v_wallet jsonb; BEGIN IF v_user_id IS NULL THEN RAISE EXCEPTION 'Usuário não autenticado'; END IF; INSERT INTO public.credit_wallets (user_id) VALUES (v_user_id) ON CONFLICT (user_id) DO NOTHING; SELECT jsonb_build_object('user_id', cw.user_id, 'balance', cw.balance, 'lifetime_earned', cw.lifetime_earned, 'lifetime_spent', cw.lifetime_spent, 'vip_tier', cw.vip_tier, 'vip_until', cw.vip_until, 'last_ad_reward_at', cw.last_ad_reward_at) INTO v_wallet FROM public.credit_wallets AS cw WHERE cw.user_id = v_user_id; RETURN v_wallet; END; $$;